function App(){
 const [staffRoute,setStaffRoute]=useState(window.location.hash==='#staff');
 useEffect(()=>{
  const onHashChange=()=>setStaffRoute(window.location.hash==='#staff');
  window.addEventListener('hashchange',onHashChange);
  return()=>window.removeEventListener('hashchange',onHashChange);
 },[]);
 return staffRoute?<StaffApp/>:<Store/>;
}

